package tmmodern;
import net.minecraft.gametest.framework.*;import net.minecraftforge.gametest.*;import net.minecraft.core.*;import net.minecraft.world.item.*;import net.minecraft.world.entity.*;import net.minecraft.world.level.block.*;
@GameTestHolder("taintedmagic") @PrefixGameTestTemplate(false)
public class TMServerTests {
    @GameTest(template="test_empty") public static void wornAmuletEnergyPriority(GameTestHelper t){var l=t.getLevel();var p=net.minecraftforge.common.util.FakePlayerFactory.get(l,new com.mojang.authlib.GameProfile(java.util.UUID.fromString("d30cbe39-4c64-4993-996f-37bc5128fb43"),"TMEnergyTest"));var inventory=top.theillusivec4.curios.api.CuriosApi.getCuriosInventory(p).resolve().orElseThrow();var necklace=inventory.getStacksHandler("necklace").orElseThrow().getStacks();var amulet=new ItemStack(tc4revival.content.TCItems.LESSER_VIS_AMULET.get());var amuletItem=(tc4revival.content.VisAmuletItem)amulet.getItem();var aer=MagicFocus.aspect("aer");amuletItem.addVis(amulet,aer,100,false,true);amuletItem.addVis(amulet,MagicFocus.aspect("perditio"),100,false,true);necklace.setStackInSlot(0,amulet);t.assertTrue(TMRuntime.consumeInventory(p,java.util.Map.of(aer,15),false)&&amuletItem.vis(amulet,aer)==100,"Flyte simulation accepts a worn amulet without consuming its vis");t.assertTrue(TMRuntime.consumeInventory(p,java.util.Map.of(aer,15),true)&&amuletItem.vis(amulet,aer)==85,"Flyte draws from equipped amulet even without an inventory wand");var tool=new ItemStack(TaintedMagic.item("thaumic_disassembler"));p.tickCount=20;tool.getItem().inventoryTick(tool,l,p,0,false);t.assertTrue(DisassemblerItem.charge(tool)==100&&amuletItem.vis(amulet,MagicFocus.aspect("perditio"))==0,"Disassembler charges from the same worn amulet through core inventory API");necklace.setStackInSlot(0,ItemStack.EMPTY);t.succeed();}
    @GameTest(template="test_empty") public static void recipesAndRegistrations(GameTestHelper t){var l=t.getLevel();for(String id:java.util.List.of("item_focus_taint_swarm","item_focus_dark_matter","item_focus_mage_mace","item_focus_shockwave","item_focus_vis_shard","item_focus_lumos","shadowmetal_ingot","void_blood_application"))t.assertTrue(l.getRecipeManager().byKey(net.minecraft.resources.ResourceLocation.parse("taintedmagic:"+id)).isPresent(),"Recipe loaded: "+id);t.assertTrue(tc4revival.content.WandParts.Rod.require("taintedmagic:warpwood").capacity()==250,"Warpwood rod capacity");t.assertTrue(tc4revival.content.WandParts.Rod.require("taintedmagic:warpwood_staff").capacity()==500,"Warpwood staff capacity");t.assertTrue(tc4revival.content.WandParts.Cap.require("taintedmagic:shadowmetal").cost==.65f,"Shadowmetal discount");t.succeed();}
    @GameTest(template="test_empty") public static void voidBloodPreservesArmor(GameTestHelper t){var grid=new net.minecraft.world.inventory.TransientCraftingContainer(new net.minecraft.world.inventory.AbstractContainerMenu(null,0){public ItemStack quickMoveStack(net.minecraft.world.entity.player.Player p,int i){return ItemStack.EMPTY;}public boolean stillValid(net.minecraft.world.entity.player.Player p){return true;}},2,2);var armor=new ItemStack(Items.DIAMOND_CHESTPLATE);armor.setDamageValue(23);armor.getOrCreateTag().putString("owner","example");grid.setItem(0,armor);grid.setItem(1,new ItemStack(TaintedMagic.item("void_blood")));var recipe=new VoidBloodRecipe(net.minecraft.resources.ResourceLocation.parse("taintedmagic:void_blood_application"),net.minecraft.world.item.crafting.CraftingBookCategory.MISC);t.assertTrue(recipe.matches(grid,t.getLevel()),"Untouched armor accepts blood");var result=recipe.assemble(grid,t.getLevel().registryAccess());t.assertTrue(result.getDamageValue()==23&&result.getTag().getString("owner").equals("example")&&result.getTag().getBoolean("voidtouched"),"Modification preserves damage and unrelated NBT");grid.setItem(0,result);t.assertTrue(!recipe.matches(grid,t.getLevel()),"Already modified armor rejected");t.succeed();}
    @GameTest(template="test_empty") public static void focusUpgradeCosts(GameTestHelper t){var focus=new ItemStack(TaintedMagic.item("focus_dark_matter"));var item=(MagicFocus)focus.getItem();t.assertTrue(item.costs(focus).get(MagicFocus.aspect("perditio"))==150,"Base dark matter centivis");item.applyUpgrade(focus,tc4revival.content.FocusUpgrade.require("taintedmagic:diffusion"),5);t.assertTrue(item.costs(focus).get(MagicFocus.aspect("perditio"))==15&&item.costs(focus).get(MagicFocus.aspect("ignis"))==10,"Diffusion costs ten percent");t.assertTrue(item.animation(focus)==tc4revival.content.WandFocusItem.Animation.CHARGE&&item.costPerTick(focus),"Diffusion continuous dispatch");t.succeed();}
    @GameTest(template="test_empty") public static void gateKeyAndDisassembler(GameTestHelper t){var l=t.getLevel();var p=net.minecraftforge.common.util.FakePlayerFactory.getMinecraft(l);var pos=t.absolutePos(new BlockPos(2,1,2));l.setBlockAndUpdate(pos,Blocks.STONE.defaultBlockState());var key=new ItemStack(TaintedMagic.item("gate_key"));p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,key);var ctx=new net.minecraft.world.item.context.UseOnContext(p,net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(pos),Direction.UP,pos,false));key.useOn(ctx);t.assertTrue(key.getTag().getInt("posY")==pos.getY()+1&&key.getTag().getString("dimension").equals(l.dimension().location().toString()),"Gate key captures dimension and space above block");var tool=new ItemStack(TaintedMagic.item("thaumic_disassembler"));tool.getOrCreateTag().putInt("charge",3);DisassemblerItem.consume(tool,80);t.assertTrue(DisassemblerItem.charge(tool)==0,"Entropy cannot become negative");p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,ItemStack.EMPTY);t.succeed();}
    @GameTest(template="test_empty",timeoutTicks=60) public static void darkMatterImpact(GameTestHelper t){var l=t.getLevel();var owner=net.minecraftforge.common.util.FakePlayerFactory.getMinecraft(l);var pos=t.absolutePos(new BlockPos(3,3,3));owner.setPos(net.minecraft.world.phys.Vec3.atCenterOf(pos.west(5)));var target=EntityType.ZOMBIE.create(l);target.setPos(net.minecraft.world.phys.Vec3.atCenterOf(pos));l.addFreshEntity(target);float health=target.getHealth();var orb=new DarkMatterProjectile(TaintedMagic.DARK.get(),l);orb.setOwner(owner);orb.setPos(target.position());orb.corrosive=true;orb.onHit(new net.minecraft.world.phys.EntityHitResult(target));t.assertTrue(target.getHealth()<health&&target.hasEffect(net.minecraft.world.effect.MobEffects.WEAKNESS)&&target.hasEffect(net.minecraft.world.effect.MobEffects.WITHER),"Original dark matter also affects undead and applies both statuses");target.discard();t.succeed();}
    @GameTest(template="test_empty") public static void armorAndKatanaDamage(GameTestHelper t){var l=t.getLevel();var p=net.minecraftforge.common.util.FakePlayerFactory.getMinecraft(l);var sword=new ItemStack(TaintedMagic.item("thaumium_katana"));sword.getOrCreateTag().putInt("inscription",0);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,sword);var fire=p.damageSources().playerAttack(p);t.assertTrue(fire.is(net.minecraft.tags.DamageTypeTags.IS_FIRE)&&!fire.is(net.minecraft.tags.DamageTypeTags.BYPASSES_ARMOR),"Fiery inscription keeps player attribution and ordinary armor");sword.getTag().putInt("inscription",1);var magic=p.damageSources().playerAttack(p);t.assertTrue(magic.is(tc4revival.content.FortressProtection.MAGIC)&&!magic.is(net.minecraft.tags.DamageTypeTags.BYPASSES_ARMOR),"Magic inscription is distinct from unblockable generic magic");p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,ItemStack.EMPTY);var boots=new ItemStack(TaintedMagic.item("voidwalker_boots"));p.setItemSlot(EquipmentSlot.FEET,boots);float remainder=tc4revival.content.FortressProtection.absorb(p,p.damageSources().playerAttack(p),10);t.assertTrue(Math.abs(remainder-(10-10*4/90f))<.001,"Voidwalker boots retain original low absorption ratio: "+remainder);int before=boots.getDamageValue();var fall=new net.minecraftforge.event.entity.living.LivingFallEvent(p,50,1);new TMRuntime().fall(fall);t.assertTrue(fall.isCanceled()&&boots.getDamageValue()==before,"Boots prevent fall damage without durability loss");p.setItemSlot(EquipmentSlot.FEET,ItemStack.EMPTY);t.succeed();}
    @GameTest(template="test_empty") public static void harvestAndSalt(GameTestHelper t){t.assertTrue(new ItemStack(TaintedMagic.item("shadowmetal_pick")).isCorrectToolForDrops(Blocks.OBSIDIAN.defaultBlockState()),"Shadowmetal harvests tier-three blocks");var l=t.getLevel();var drop=new net.minecraft.world.entity.item.ItemEntity(l,t.absolutePos(new BlockPos(2,1,2)).getX(),10,2,new ItemStack(TaintedMagic.item("salis_aevus")));var tag=new net.minecraft.nbt.CompoundTag();drop.saveWithoutId(tag);tag.putShort("Age",(short)100);drop.load(tag);l.setDayTime(26000);TMRuntime.saltTick(drop,(UtilityItem)drop.getItem().getItem());t.assertTrue(l.getDayTime()==38000&&drop.isRemoved(),"Time salts advance to night within current day rather than rolling calendar back");t.succeed();}
}
